// src/auth/log.ts
function format(level, message, extra) {
  const suffix = extra && Object.keys(extra).length > 0 ? ` ${JSON.stringify(extra)}` : "";
  return `[deveco-harness:auth] ${level} ${message}${suffix}`;
}
function debugEnabled() {
  const value = process.env.DEVECO_HARNESS_DEBUG ?? process.env.DEBUG ?? "";
  return value === "1" || value === "true" || value.includes("deveco");
}
function logInfo(message, extra) {
  if (!debugEnabled())
    return;
  console.error(format("info", message, extra));
}
function logWarn(message, extra) {
  console.error(format("warn", message, extra));
}
function logError(message, extra) {
  console.error(format("error", message, extra));
}

// src/auth/browser.ts
async function openBrowser(loginUrl) {
  const safeUrl = loginUrl.replace(/code=[^&]*/g, "code=***");
  let parsed;
  try {
    parsed = new URL(loginUrl);
  } catch (err) {
    logError("invalid login URL", { service: "deveco", url: safeUrl });
    throw new Error("Invalid login URL", { cause: err });
  }
  if (parsed.protocol !== "https:" && parsed.protocol !== "http:") {
    logError("unsupported login URL scheme", { service: "deveco", scheme: parsed.protocol, url: safeUrl });
    throw new Error(`Unsupported login URL scheme: ${parsed.protocol}`);
  }
  if (!/^[A-Za-z0-9._~:/?=&%#@+-]+$/.test(parsed.href)) {
    logError("login URL contains disallowed characters", { service: "deveco", url: safeUrl });
    throw new Error("Login URL contains disallowed characters");
  }
  const href = parsed.href;
  try {
    await new Promise((resolve, reject) => {
      const child = process.platform === "win32" ? spawn("rundll32", ["url.dll,FileProtocolHandler", href], { detached: true, stdio: "ignore" }) : process.platform === "darwin" ? spawn("open", [href], { detached: true, stdio: "ignore" }) : spawn("xdg-open", [href], { detached: true, stdio: "ignore" });
      child.on("error", reject);
      child.unref();
      setImmediate(resolve);
    });
  } catch (err) {
    logError("failed to open login page in browser", {
      service: "deveco",
      error: err instanceof Error ? err.message : String(err)
    });
    throw new Error("Failed to open login page", { cause: err });
  }
}

