class LocalAuthServer {
  baseUrl;
  successRedirectUrl;
  failedRedirectUrl;
  server = null;
  port;
  loginState;
  callbackPath = "/callback";
  resolveCallback = null;
  rejectCallback = null;
  timeoutId = null;
  constructor(port, loginState, baseUrl, successRedirectUrl, failedRedirectUrl) {
    this.baseUrl = baseUrl;
    this.successRedirectUrl = successRedirectUrl;
    this.failedRedirectUrl = failedRedirectUrl;
    this.port = port;
    this.loginState = loginState;
  }
  async start() {
    const portsToTry = [this.port, 34567, 34568, 34569, 34570];
    for (const port of portsToTry) {
      try {
        this.port = await this.tryPort(port);
        return this.port;
      } catch {
        if (port === portsToTry[portsToTry.length - 1]) {
          logError("all auth server ports are in use", { service: "deveco", ports: portsToTry });
          throw new Error("All ports are in use. Please free up a port or close other DevEco login attempts.");
        }
      }
    }
    throw new Error("Failed to start server");
  }
  tryPort(port) {
    return new Promise((resolve, reject) => {
      const server = http2.createServer((req, res) => {
        this.handleRequest(req, res);
      });
      server.on("error", (err) => {
        if (err.code === "EADDRINUSE") {
          reject(new Error("Port is already in use"));
        } else {
          reject(err);
        }
      });
      server.listen(port, "127.0.0.1", () => {
        this.server = server;
        resolve(port);
      });
    });
  }
  async waitForCallback(timeout = 30000) {
    return new Promise((resolve, reject) => {
      this.resolveCallback = (value) => {
        if (this.timeoutId) {
          clearTimeout(this.timeoutId);
          this.timeoutId = null;
        }
        resolve(value);
      };
      this.rejectCallback = (reason) => {
        if (this.timeoutId) {
          clearTimeout(this.timeoutId);
          this.timeoutId = null;
        }
        reject(reason);
      };
      this.timeoutId = setTimeout(() => {
        this.timeoutId = null;
        this.rejectCallback?.(new Error("Callback timeout"));
      }, timeout);
    });
  }
  cancel() {
    if (this.rejectCallback) {
      this.rejectCallback(new LoginCancelledError("Login cancelled by user"));
      this.rejectCallback = null;
      this.resolveCallback = null;
    }
    if (this.timeoutId) {
      clearTimeout(this.timeoutId);
      this.timeoutId = null;
    }
  }
  async stop() {
    if (this.timeoutId) {
      clearTimeout(this.timeoutId);
      this.timeoutId = null;
    }
    return new Promise((resolve, reject) => {
      if (!this.server) {
        resolve();
        return;
      }
      this.server.close((error) => {
        if (error)
          reject(error);
        else
          resolve();
      });
    });
  }
  handleRequest(req, res) {
    const host = req.headers.host || `localhost:${this.port}`;
    const url = new URL3(req.url ?? "", `http://${host}`);
    if (url.pathname !== this.callbackPath) {
      res.writeHead(404);
      res.end("Not Found");
      return;
    }
    try {
      const urlParams = url.searchParams;
      if (req.method === "POST") {
        let body = "";
        req.on("data", (chunk) => {
          body += chunk.toString();
        });
        req.on("end", () => {
          this.handleCallbackRequest(res, urlParams, body);
        });
      } else {
        this.handleCallbackRequest(res, urlParams, "");
      }
    } catch (err) {
      res.writeHead(500);
      res.end("Internal Server Error");
      logError("local auth server request error", {
        service: "deveco",
        error: err instanceof Error ? err.message : String(err)
      });
      this.rejectCallback?.(err instanceof Error ? err : new Error(String(err)));
    }
  }
  handleCallbackRequest(res, urlParams, body) {
    try {
      const params = body.trim() ? new URLSearchParams(body) : urlParams;
      const code = params.get("code");
      const tempToken = params.get("tempToken");
      const siteId = params.get("siteId");
      const quit = params.get("quit");
      if (!code || code !== this.loginState) {
        logWarn("login callback: code mismatch or missing, ignoring", { service: "deveco", hasCode: !!code });
        return;
      }
      if (quit === "true" || quit === "access_denied") {
        logInfo("login callback: user cancelled", { service: "deveco", quit });
        this.rejectCallback?.(new LoginCancelledError(quit === "access_denied" ? "Access denied by user" : "Login cancelled by user"));
        res.writeHead(302, { Location: `${this.baseUrl}/${this.failedRedirectUrl}` });
        res.end();
        return;
      }
      if (!tempToken || !siteId) {
        logError("login callback: missing tempToken or siteId", {
          service: "deveco",
          tempToken: !!tempToken,
          siteId: !!siteId
        });
        this.rejectCallback?.(new Error("Login cancelled by user"));
        res.writeHead(302, { Location: `${this.baseUrl}/${this.failedRedirectUrl}` });
        res.end();
        return;
      }
      if (siteId !== "1") {
        logError("login callback: unsupported region", { service: "deveco", siteId });
        this.rejectCallback?.(new UnsupportedRegionError("Unsupported region"));
        res.writeHead(302, { Location: `${this.baseUrl}/${this.failedRedirectUrl}` });
        res.end();
        return;
      }
      this.resolveCallback?.({
        tempToken,
        siteId,
        quit: quit ?? undefined
      });
      res.writeHead(302, { Location: `${this.baseUrl}/${this.successRedirectUrl}` });
      res.end();
    } catch (err) {
      res.writeHead(500);
      res.end("Internal Server Error");
      logError("local auth server callback error", {
        service: "deveco",
        error: err instanceof Error ? err.message : String(err)
      });
      this.rejectCallback?.(err instanceof Error ? err : new Error(String(err)));
    }
  }
  getPort() {
    return this.port;
  }
}

